// Lazy-loaded only on a checker PDF click. No names, results or generated bytes
// are sent to a server; only the fixed public artwork and font URLs are fetched.
import { PDFDocument } from 'pdf-lib';
import { loadRecipientFont, recipientCanvasFont, recipientDisplayName } from '../lib/giftFonts.js';
import { fitCertificatePreviewName } from '../lib/santaPictureLayout.js';

async function artwork(result, signal) {
  const response = await fetch(`/certificates/checker/${result}-master.webp`, { credentials: 'omit', signal });
  if (!response.ok) throw new Error('Certificate artwork could not load');
  const url = URL.createObjectURL(await response.blob());
  const image = new Image();
  try {
    image.src = url;
    await image.decode();
    return image;
  } finally { URL.revokeObjectURL(url); }
}

export async function exportCheckerCertificate(name, result, { signal } = {}) {
  if (!['nice', 'naughty'].includes(result)) throw new Error('Invalid certificate result');
  const [image] = await Promise.all([
    artwork(result, signal), loadRecipientFont(),
  ]);
  if (signal?.aborted) throw new DOMException('Cancelled', 'AbortError');
  const canvas = document.createElement('canvas');
  canvas.width = image.naturalWidth; canvas.height = image.naturalHeight;
  const context = canvas.getContext('2d');
  if (!context) throw new Error('Certificate drawing is unavailable');
  context.drawImage(image, 0, 0);
  const fit = fitCertificatePreviewName(context, name);
  context.save();
  context.scale(canvas.width / 297, canvas.height / 210);
  context.font = recipientCanvasFont(fit.size); context.fontKerning = 'none';
  context.fillStyle = '#f1d995';
  context.fillText(recipientDisplayName(name), fit.x, fit.y);
  context.restore();
  const png = await new Promise((resolve, reject) => canvas.toBlob(
    blob => blob ? blob.arrayBuffer().then(resolve, reject) : reject(new Error('Certificate image could not be created')), 'image/png'));
  if (signal?.aborted) throw new DOMException('Cancelled', 'AbortError');
  const pdf = await PDFDocument.create();
  pdf.setTitle(`Head Elf’s Very Unofficial ${result === 'nice' ? 'Nice' : 'Naughty'} List Certificate`);
  const page = pdf.addPage([841.8898, 595.2756]);
  page.drawImage(await pdf.embedPng(png), { x: 0, y: 0, width: page.getWidth(), height: page.getHeight() });
  return new Blob([await pdf.save()], { type: 'application/pdf' });
}
